/* Remaining four observed bank01 pure instructions. The JMP changes only
 * architectural PC; CALL/return instructions still use the518 supervisor seam. */
typedef struct Pure527Site {uint32_t pc;uint8_t bytes[3],length,cycles;} Pure527Site;
static const Pure527Site pure527_sites[]={
    {0x0180a0,{0x9c,0x53,0x05},3,4},
    {0x0184c7,{0x4c,0x06,0x84},3,3},
    {0x018406,{0xe2,0x20,0},2,3},
    {0x018408,{0xa9,0x01,0},2,2}
};
static int pure527_enabled=-1,pure527_installed,pure527_identity,pure527_report;
static const uint8_t*pure527_rom;static size_t pure527_size;
static uint64_t pure527_done[4];
static void Pure527Report(void) {
    if(!pure527_report)return;
    fprintf(stderr,"[native-bank01-pure527] original_cost=1");
    for(unsigned n=0;n<4;++n)fprintf(stderr," pc%06x=%llu",pure527_sites[n].pc,(unsigned long long)pure527_done[n]);
    fputc('\n',stderr);
}
static void Pure527Instruction(CpuState*c,uint32_t pc) {
    if(!pure527_enabled||!pure527_identity||c!=&g_cpu||!g_snes||!g_snes->cart||
       g_rom!=pure527_rom||g_snes->cart->romImageSize!=pure527_size||
       c->emulation||c->PB!=1||c->DB!=1||(pc>>16)!=1||
       c->m_flag>1||c->x_flag>1||
       (c->x_flag&&(c->X>255||c->Y>255))||c->P!=Poll506P(c))return;
    unsigned n;for(n=0;n<4;++n)if(pure527_sites[n].pc==pc)break;
    if(n==4)return;
    const Pure527Site*s=&pure527_sites[n];
    /* Immediate LDA and STZ have eight-bit accumulator source variants here.
     * JMP and SEP#$20 are independent of both incoming widths. X=0 retains
     * all sixteen index bits; setting M never truncates index registers. */
    if((s->bytes[0]==0xa9||s->bytes[0]==0x9c)&&!c->m_flag)return;
    size_t offset=0x8000+(pc&0x7fff);
    if(offset+s->length>pure527_size||memcmp(g_rom+offset,s->bytes,s->length))return;
    if(!interp_bridge_native_begin(c))return;
    for(unsigned i=0;i<s->length;++i)
        if(interp_bridge_native_read8(c,pc+i)!=s->bytes[i]) {
            fputs("[native-bank01-pure527] original fetch changed\n",stderr);abort();
        }
    uint32_t next=pc+s->length;
    switch(s->bytes[0]) {
    case 0x9c:
        interp_bridge_native_write8(c,(uint32_t)c->DB<<16|0x0553,0);break;
    case 0x4c:next=(pc&0xff0000)|0x8406;break;
    case 0xe2:c->m_flag=1;break;
    default:
        c->A=(c->A&0xff00)|1;c->_flag_N=0;c->_flag_Z=0;break;
    }
    cpu_mirrors_to_p(c);interp_bridge_native_commit(c,s->cycles,next);++pure527_done[n];
}
static void Pure527BeforeFrame(void) {
    if(pure527_enabled<0) {
        const char*v=getenv("SNESRECOMP_FOUNDATION_NATIVE_BANK01_PURE");
        pure527_enabled=!v||!strcmp(v,"1")||!strcmp(v,"original");
        v=getenv("SNESRECOMP_FOUNDATION_NATIVE_BANK01_PURE_REPORT");
        pure527_report=v&&!strcmp(v,"1");atexit(Pure527Report);
    }
    if(!pure527_enabled||!g_snes||!g_snes->cart||!g_rom)return;
    size_t size=g_snes->cart->romImageSize;
    if(pure527_rom!=g_rom||pure527_size!=size) {
        static const uint8_t clean[32]={
            0x7d,0xa4,0xa3,0xcf,0xa5,0xde,0x4b,0xb4,0x72,0x2a,0x6e,0x2a,0x42,0xc2,0x6a,0xae,
            0x32,0x2b,0x5e,0x66,0x8f,0x16,0x45,0xd8,0xc8,0x70,0xfb,0x99,0xe6,0x08,0x06,0x00};
        pure527_rom=g_rom;pure527_size=size;pure527_identity=0;
        if(size==1572864){uint8_t hash[32];sha256_compute(g_rom,size,hash);pure527_identity=!memcmp(hash,clean,32);}
    }
    if(!pure527_identity||pure527_installed)return;
    pure527_installed=1;
    for(unsigned n=0;n<4;++n)
        if(!interp_bridge_add_pre_opcode_hook(pure527_sites[n].pc,Pure527Instruction)) {
            pure527_enabled=0;fputs("[native-bank01-pure527] registration refused; original instructions retained\n",stderr);break;
        }
}

