static void Family534Instruction(CpuState*c,uint32_t pc){
 if(!family534_ready||c!=&g_cpu||!g_snes||!g_snes->cart||
    g_rom!=family534_rom||g_snes->cart->romImageSize!=family534_size||c->emulation||
    c->PB!=2||c->DB!=2||(pc>>16)!=2||c->m_flag>1||c->x_flag>1||
    (c->x_flag&&(c->X>255||c->Y>255))||c->P!=Poll506P(c))return;
 unsigned n;for(n=0;n<20;++n)if(family534_sites[n].pc==pc)break;
 if(n==20)return;
 const Family534Site*s=&family534_sites[n];unsigned op=s->bytes[0];
 /* These operand/data variants are eight-bit A. Control, REP/SEP and TAX
  * are width-independent source operations; TAX uses all sixteen A bits
  * when X=0 even if M=1. The indexed store is the observed X=1 WRAM form. */
 if((op==0xa9||op==0xad||op==0x9c||op==0xc9||op==0x4a||op==0x9d)&&!c->m_flag)return;
 if(op==0x9d&&!c->x_flag)return;
 size_t offset=0x10000+(pc&0x7fff);
 if(offset+s->length>family534_size||memcmp(g_rom+offset,s->bytes,s->length))return;
 if(!interp_bridge_native_begin(c))return;
 for(unsigned i=0;i<s->length;++i)if(interp_bridge_native_read8(c,pc+i)!=s->bytes[i]){
  fputs("[native-bank02-family534] original fetch changed\n",stderr);abort();
 }
 uint32_t next=pc+s->length;unsigned cycles=s->cycles;
 unsigned operand=s->bytes[1]|(unsigned)s->bytes[2]<<8;
 switch(op){
 case 0xc2:c->m_flag=0;break;
 case 0xe2:
  c->m_flag=1;
  if(operand&0x10){c->x_flag=1;c->X&=255;c->Y&=255;}
  break;
 case 0xa9:case 0xad:{
  unsigned value=op==0xa9?s->bytes[1]:interp_bridge_native_read8(c,(uint32_t)c->DB<<16|operand);
  c->A=(c->A&0xff00)|value;c->_flag_N=!!(value&0x80);c->_flag_Z=value==0;break;
 }
 case 0x9c:interp_bridge_native_write8(c,(uint32_t)c->DB<<16|operand,0);break;
 case 0x9d:interp_bridge_native_write8(c,((uint32_t)c->DB<<16|operand)+c->X,(uint8_t)c->A);break;
 case 0xc9:{unsigned value=c->A&255,difference=(value-s->bytes[1])&255;c->_flag_C=value>=s->bytes[1];c->_flag_N=!!(difference&0x80);c->_flag_Z=difference==0;break;}
 case 0x4a:{unsigned value=c->A&255;c->_flag_C=value&1;value>>=1;c->A=(c->A&0xff00)|value;c->_flag_N=0;c->_flag_Z=value==0;break;}
 case 0xaa:
  c->X=c->x_flag?(c->A&255):c->A;
  c->_flag_N=!!(c->X&(c->x_flag?0x80:0x8000));c->_flag_Z=c->X==0;break;
 default:{
  unsigned taken=op==0x90?!c->_flag_C:op==0xd0?!c->_flag_Z:c->_flag_Z;
  if(taken){next=(pc&0xff0000)|((pc+2+(int8_t)s->bytes[1])&0xffff);++cycles;}
  break;
 }
 }
 cpu_mirrors_to_p(c);interp_bridge_native_commit(c,cycles,next);++family534_done[n];
}
