static int condition573_enabled=-1,condition573_ready,condition573_installed,condition573_report;
static void Condition573Report(void){
 if(!condition573_report)return;fputs("[native-condition-family573] original_cost=1",stderr);
 for(unsigned n=0;n<sizeof(condition573_sites)/sizeof(condition573_sites[0]);++n)fprintf(stderr," pc%06x=%llu",condition573_sites[n].pc,
  (unsigned long long)interp_bridge_native_control_site_count(condition573_sites[n].pc));
 fputc('\n',stderr);
}
static void Condition573BeforeFrame(void){
 if(condition573_enabled<0){const char*v=getenv("SNESRECOMP_FOUNDATION_NATIVE_CONDITION_FAMILY");
  condition573_enabled=!v||!strcmp(v,"1")||!strcmp(v,"original");
  v=getenv("SNESRECOMP_FOUNDATION_NATIVE_CONDITION_FAMILY_REPORT");condition573_report=v&&!strcmp(v,"1");atexit(Condition573Report);}
 static const uint8_t*bound_rom;static size_t bound_size;static int identity;
 condition573_ready=0;
 if(!condition573_enabled||!g_snes||!g_snes->cart||!g_rom)return;
 size_t size=g_snes->cart->romImageSize;
 if(bound_rom!=g_rom||bound_size!=size){
  static const uint8_t clean[32]={
   0x7d,0xa4,0xa3,0xcf,0xa5,0xde,0x4b,0xb4,0x72,0x2a,0x6e,0x2a,0x42,0xc2,0x6a,0xae,
   0x32,0x2b,0x5e,0x66,0x8f,0x16,0x45,0xd8,0xc8,0x70,0xfb,0x99,0xe6,0x08,0x06,0x00};
  bound_rom=g_rom;bound_size=size;identity=0;
  if(size==1572864){uint8_t hash[32];sha256_compute(g_rom,size,hash);identity=!memcmp(hash,clean,32);}}
 if(!identity)return;condition573_ready=1;if(condition573_installed)return;condition573_installed=1;
 for(unsigned n=0;n<sizeof(condition573_sites)/sizeof(condition573_sites[0]);++n){const Condition573Site*s=&condition573_sites[n];
  if(s->bytes[0]==0x22||s->bytes[0]==0x20||s->bytes[0]==0x60){if(!interp_bridge_add_native_control_site(s->pc,s->bytes,s->length,&condition573_ready))goto refused;}
  else if(!interp_bridge_add_native_condition_site(s->pc,s->bytes,s->length,s->mask,&condition573_ready))goto refused;}
 return;
refused:condition573_enabled=condition573_ready=0;
 fputs("[native-condition-family573] registration refused; original instructions retained\n",stderr);
}

