static void FinalBattle642Report(void){
 if(!battle642_report)return;fputs("[native-final-battle642] original_cost=1",stderr);
 for(unsigned n=0;n<sizeof(battle642_sites)/sizeof(battle642_sites[0]);++n)fprintf(stderr," pc%06x=%llu",battle642_sites[n].pc,
  (unsigned long long)interp_bridge_native_control_site_count(battle642_sites[n].pc));
 fputc('\n',stderr);
}
static void FinalBattle642BeforeFrame(void){
 if(battle642_enabled<0){const char*v=getenv("SNESRECOMP_FOUNDATION_NATIVE_FINAL_BATTLE");
  battle642_enabled=!v||!strcmp(v,"1")||!strcmp(v,"original");
  v=getenv("SNESRECOMP_FOUNDATION_NATIVE_FINAL_BATTLE_REPORT");battle642_report=v&&!strcmp(v,"1");atexit(FinalBattle642Report);}
 static const uint8_t*bound_rom;static size_t bound_size;static int identity;
 battle642_ready=0;
 if(!battle642_enabled||!g_snes||!g_snes->cart||!g_rom)return;
 size_t size=g_snes->cart->romImageSize;
 if(bound_rom!=g_rom||bound_size!=size){
  static const uint8_t clean[32]={
   0x7d,0xa4,0xa3,0xcf,0xa5,0xde,0x4b,0xb4,0x72,0x2a,0x6e,0x2a,0x42,0xc2,0x6a,0xae,
   0x32,0x2b,0x5e,0x66,0x8f,0x16,0x45,0xd8,0xc8,0x70,0xfb,0x99,0xe6,0x08,0x06,0x00};
  bound_rom=g_rom;bound_size=size;identity=0;
  if(size==1572864){uint8_t hash[32];sha256_compute(g_rom,size,hash);identity=!memcmp(hash,clean,32);}}
 if(!identity)return;battle642_ready=1;if(battle642_installed)return;battle642_installed=1;
 for(unsigned n=0;n<sizeof(battle642_sites)/sizeof(battle642_sites[0]);++n){const FinalBattle642Site*s=&battle642_sites[n];
  if(!interp_bridge_add_native_condition_site(s->pc,s->bytes,s->length,s->mask,&battle642_ready))goto refused;}
 return;
refused:battle642_enabled=battle642_ready=0;
 fputs("[native-final-battle642] registration refused; original instructions retained\n",stderr);
}

