static int rename709_enabled=-1,rename709_ready,rename709_installed,rename709_report;
static void Rename709Report(void){
 if(!rename709_report)return;fputs("[native-rename709] original_cost=1",stderr);
 for(unsigned n=0;n<sizeof(rename709_sites)/sizeof(rename709_sites[0]);++n)fprintf(stderr," pc%06x=%llu",rename709_sites[n].pc,
  (unsigned long long)interp_bridge_native_condition_gate_count(rename709_sites[n].pc,&rename709_ready));
 fputc('\n',stderr);
}
static void Rename709BeforeFrame(void){
 if(rename709_enabled<0){const char*v=getenv("SNESRECOMP_FOUNDATION_NATIVE_RENAME");
  rename709_enabled=!v||!strcmp(v,"1")||!strcmp(v,"original");
  v=getenv("SNESRECOMP_FOUNDATION_NATIVE_RENAME_REPORT");rename709_report=v&&!strcmp(v,"1");atexit(Rename709Report);}
 static const uint8_t*bound_rom;static size_t bound_size;static int identity;
 rename709_ready=0;
 if(!rename709_enabled||!g_snes||!g_snes->cart||!g_rom)return;
 size_t size=g_snes->cart->romImageSize;
 if(bound_rom!=g_rom||bound_size!=size){
  static const uint8_t clean[32]={
   0x7d,0xa4,0xa3,0xcf,0xa5,0xde,0x4b,0xb4,0x72,0x2a,0x6e,0x2a,0x42,0xc2,0x6a,0xae,
   0x32,0x2b,0x5e,0x66,0x8f,0x16,0x45,0xd8,0xc8,0x70,0xfb,0x99,0xe6,0x08,0x06,0x00};
  bound_rom=g_rom;bound_size=size;identity=0;
  if(size==1572864){uint8_t hash[32];sha256_compute(g_rom,size,hash);identity=!memcmp(hash,clean,32);}}
 if(!identity)return;rename709_ready=1;if(rename709_installed)return;rename709_installed=1;
 for(unsigned n=0;n<sizeof(rename709_sites)/sizeof(rename709_sites[0]);++n){const Rename709Site*s=&rename709_sites[n];
  if(!(s->mode_extension?interp_bridge_add_native_condition_mode_site(s->pc,s->bytes,s->length,s->mask,&rename709_ready):interp_bridge_add_native_condition_site(s->pc,s->bytes,s->length,s->mask,&rename709_ready)))goto refused;}
 return;
refused:rename709_enabled=rename709_ready=0;
 fputs("[native-rename709] registration refused; original instructions retained\n",stderr);
}

