static int sort717_enabled=-1,sort717_ready,sort717_installed,sort717_report;
static void Sort717Report(void){
 if(!sort717_report)return;fputs("[native-sort717] original_cost=1",stderr);
 for(unsigned n=0;n<sizeof(sort717_sites)/sizeof(sort717_sites[0]);++n)fprintf(stderr," pc%06x=%llu",sort717_sites[n].pc,
  (unsigned long long)interp_bridge_native_condition_gate_count(sort717_sites[n].pc,&sort717_ready));
 fputc('\n',stderr);
}
static void Sort717BeforeFrame(void){
 if(sort717_enabled<0){const char*v=getenv("SNESRECOMP_FOUNDATION_NATIVE_SORT");
  sort717_enabled=!v||!strcmp(v,"1")||!strcmp(v,"original");
  v=getenv("SNESRECOMP_FOUNDATION_NATIVE_SORT_REPORT");sort717_report=v&&!strcmp(v,"1");atexit(Sort717Report);}
 static const uint8_t*bound_rom;static size_t bound_size;static int identity;
 sort717_ready=0;
 if(!sort717_enabled||!g_snes||!g_snes->cart||!g_rom)return;
 size_t size=g_snes->cart->romImageSize;
 if(bound_rom!=g_rom||bound_size!=size){
  static const uint8_t clean[32]={
   0x7d,0xa4,0xa3,0xcf,0xa5,0xde,0x4b,0xb4,0x72,0x2a,0x6e,0x2a,0x42,0xc2,0x6a,0xae,
   0x32,0x2b,0x5e,0x66,0x8f,0x16,0x45,0xd8,0xc8,0x70,0xfb,0x99,0xe6,0x08,0x06,0x00};
  bound_rom=g_rom;bound_size=size;identity=0;
  if(size==1572864){uint8_t hash[32];sha256_compute(g_rom,size,hash);identity=!memcmp(hash,clean,32);}}
 if(!identity)return;sort717_ready=1;if(sort717_installed)return;sort717_installed=1;
 for(unsigned n=0;n<sizeof(sort717_sites)/sizeof(sort717_sites[0]);++n){const Sort717Site*s=&sort717_sites[n];
  if(!(s->mode_extension?interp_bridge_add_native_condition_mode_site(s->pc,s->bytes,s->length,s->mask,&sort717_ready):interp_bridge_add_native_condition_site(s->pc,s->bytes,s->length,s->mask,&sort717_ready)))goto refused;}
 return;
refused:sort717_enabled=sort717_ready=0;
 fputs("[native-sort717] registration refused; original instructions retained\n",stderr);
}

void FoundationRulesInit(void) {
    ItemEffects668BeforeFrame();
    EquipmentChange660BeforeFrame();
    Equipment653BeforeFrame();
    FinalBattle642BeforeFrame();
    Residual634BeforeFrame();
    ItemContinuation626BeforeFrame();
    Menu618BeforeFrame();
    Item610BeforeFrame();
    FieldTail601BeforeFrame();
    Field593BeforeFrame();
    Message586BeforeFrame();
    Condition573BeforeFrame();
    Condition568BeforeFrame();
    Field565BeforeFrame();
    Dispatcher554BeforeFrame();
    Poll506BeforeFrame();
    Record514BeforeFrame();
    Control518BeforeFrame();
    Pure527BeforeFrame();
    Family534BeforeFrame();
    Stack540BeforeFrame();
    Index547BeforeFrame();
    FieldMenus677BeforeFrame();
    Magic685BeforeFrame();
    BattleMagic693BeforeFrame();
    Shop701BeforeFrame();
    Rename709BeforeFrame();
    Sort717BeforeFrame();
    static int initialized;
    if (initialized) return;
    initialized = 1;
    if (getenv("SNESRECOMP_FOUNDATION_WAIT_TRACE")) {
        interp_bridge_add_pre_opcode_hook(0x00ff03, TraceFrameWait);
        interp_bridge_add_pre_opcode_hook(0x02911b, TraceFrameWait);
    }
    const char *value = getenv("SNESRECOMP_FOUNDATION_DAMAGE_PROOF");
    multiplier = value && !strcmp(value, "2") ? 2 : 1;
    trace = value && !strcmp(value, "trace");
    if (multiplier != 1 || trace) {
        if (!interp_bridge_add_pre_opcode_hook(0x00dc97, BeforeEnemyHpCompare)) {
            multiplier = 1;
            fprintf(stderr, "[foundation_rule] registration refused; original damage retained\n");
        }
    }
}
